const tls = require('tls');
const BLOCKED = /^(localhost|.*\.local|.*\.internal|.*\.lan)$/i;
const PRIVATE = /^(10\.|127\.|0\.|192\.168\.|169\.254\.|172\.(1[6-9]|2\d|3[01])\.)/;

function probe(host, port) {
  return new Promise(resolve => {
    const sock = tls.connect({ host, port, servername: host, rejectUnauthorized: false }, () => {
      const c = sock.getPeerCertificate();
      sock.end();
      resolve({ ok: !!(c && c.valid_to), cert: c });
    });
    sock.setTimeout(10000, () => { sock.destroy(); resolve({ ok: false, error: 'timeout' }); });
    sock.on('error', e => resolve({ ok: false, error: e.message }));
  });
}

const items = $input.all();
const out = [];
const stats = { total: items.length, checked: 0, failed: 0, findings: 0 };

for (let i = 0; i < items.length; i += 5) {
  const chunk = items.slice(i, i + 5);
  const results = await Promise.all(chunk.map(async it => {
    const v = it.json;
    let host, port;
    try {
      const u = new URL(/^https?:\/\//i.test(v.website) ? v.website : 'https://' + v.website);
      host = u.hostname; port = Number(u.port) || 443;
    } catch (e) { return { v, error: 'invalid_url' }; }
    if (BLOCKED.test(host) || PRIVATE.test(host)) return { v, host, port, error: 'blocked_host' };
    return { v, host, port, ...(await probe(host, port)) };
  }));
  for (const r of results) {
    if (!r.ok) { stats.failed++; continue; }
    stats.checked++;
    const notAfter = new Date(r.cert.valid_to);
    const daysLeft = Math.floor((notAfter - Date.now()) / 86400000);
    const severity = daysLeft < 7 ? 'critical' : daysLeft < 30 ? 'high' : daysLeft < 60 ? 'medium' : null;
    if (!severity) continue;
    const issuer = (r.cert.issuer && (r.cert.issuer.O || r.cert.issuer.CN)) || 'n/a';
    stats.findings++;
    out.push({ json: {
      kind: 'finding', vendor_id: r.v.id, source: 'tls_expiry',
      // El nivel de severidad forma parte de la referencia: escalar de nivel genera un hallazgo nuevo (y una alerta).
      source_ref: 'tls:' + r.host + ':' + r.port + ':' + notAfter.toISOString().slice(0, 10) + ':' + severity,
      title: daysLeft < 0 ? 'Certificado TLS EXPIRADO (' + r.host + ')'
                          : 'Certificado TLS expira en ' + daysLeft + ' días (' + r.host + ')',
      description: 'Emisor: ' + issuer + ' · Válido hasta ' + notAfter.toISOString(),
      severity,
      evidence: { host: r.host, port: r.port, days_left: daysLeft, issuer, not_after: notAfter.toISOString(),
                  subject: r.cert.subject && r.cert.subject.CN }
    }});
  }
}
out.push({ json: { kind: 'summary', job_type: 'tls_expiry', interval_min: 1440,
  status: stats.checked === 0 && stats.total > 0 ? 'error' : (stats.failed > 0 ? 'partial' : 'ok'),
  meta: stats } });
return out;
